    @pytest.mark.valid
    def test_large_image_varying_values(self):
        # Arrange
        size = 100
        image = Image.new('L', (size, size), 128)
        pixels = image.load()
        for i in range(size):
            for j in range(size):
                pixels[i, j] = i * j % 256

        # Act
        result_image = mean_threshold(image)

        # Assert
